<script setup lang="ts">import AppLayout from '@/Layouts/AppLayout.vue'; import { useForm } from '@inertiajs/vue3'; defineProps<{ priorities: string[] }>(); const form=useForm({title:'',description:'',deadline:'',priority:'MEDIUM',total_price:0,worker_fee:0}); const submit=()=>form.post(route('orders.store'));</script><template><AppLayout><div class="card mx-auto max-w-3xl"><h1 class="text-2xl font-black">Create order</h1><form class="mt-6 space-y-4" @submit.prevent="submit"><input v-model="form.title" class="w-full rounded-2xl border-white/10 bg-white/10" placeholder="Title"><textarea v-model="form.description" class="h-40 w-full rounded-2xl border-white/10 bg-white/10" placeholder="Brief"/><div class="grid gap-4 md:grid-cols-2"><input v-model="form.deadline" type="datetime-local" class="rounded-2xl border-white/10 bg-white/10"><select v-model="form.priority" class="rounded-2xl border-white/10 bg-white/10"><option v-for="priority in priorities" :key="priority">{{ priority }}</option></select><input v-model="form.total_price" type="number" class="rounded-2xl border-white/10 bg-white/10" placeholder="Total price"><input v-model="form.worker_fee" type="number" class="rounded-2xl border-white/10 bg-white/10" placeholder="Worker fee"></div><button class="btn-primary" :disabled="form.processing">Submit order</button></form></div></AppLayout></template>
